excels.excel:

EXPORT WITH SHEET="会议费用报销明细表", HEADER=true,
    MAPPING={"a":"会议名称","b":"举办日期","c":"场地费","d":"餐饮费","e":"住宿费","f":"合计金额","g":"审批状态"},
    FORMAT={"b":"yyyy-MM-dd","c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","f":"#,##0.00"},
    FORMULAS={
        F2:'C2+D2+E2',F3:'C3+D3+E3',F4:'C4+D4+E4',F5:'C5+D5+E5',F6:'C6+D6+E6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',F7:'C7+D7+E7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F3:{color:red,bold:true}
    }
